int jump(int *nums, int numsSize) {
  int jumps = 0, curEnd = 0, farthest = 0;
  for (int i = 0; i < numsSize - 1; i++) {
    if (i + nums[i] > farthest) {
      farthest = i + nums[i];
    }
    if (i == curEnd) {
      jumps++;
      curEnd = farthest;
    }
  }
  return jumps;
}

class Solution {
public:
  int jump(vector<int> &nums) {
    int jumps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < (int)nums.size() - 1; i++) {
      farthest = max(farthest, i + nums[i]);
      if (i == curEnd) {
        jumps++;
        curEnd = farthest;
      }
    }
    return jumps;
  }
};

